/// Bir karar kartı: danışman, mevsim (0 her mevsim), soru ve iki seçenek.
/// Metinler 33 dilde (studio-core Strings.languages sırası).
class KCard {
  final int who, season;
  final List<String> q, l, r;

  /// Etkiler: halk, hazine, ordu, doğa.
  final List<int> le, re;
  const KCard(this.who, this.season, this.q, this.l, this.r, this.le, this.re);

  String get qTr => q[0];
  String get qEn => q[1];
  String question(String lang) => Strings.pick(q, lang);
  String left(String lang) => Strings.pick(l, lang);
  String right(String lang) => Strings.pick(r, lang);
}

